using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class SpinAudienceChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var m=JsonUtility.FromJson<SocialMemory>("{}");Require(m.Valid()&&m.tricksEnjoyed==0,"Historical social save rejected");Require(m.RememberTrick(1)&&m.tricksEnjoyed==1&&!m.RememberTrick(2),"Trick enjoyment duplicated");Require(m.trust>.45f&&m.trickInterest>.5f,"Enjoyment did not change preference/sentiment");Require(m.RememberTrick(91),"Trick cooldown never recovers");var loaded=JsonUtility.FromJson<SocialMemory>(JsonUtility.ToJson(m));Require(loaded.Valid()&&loaded.tricksEnjoyed==2&&loaded.nextTrickAt==181,"Trick memory did not round-trip");loaded.trickInterest=float.NaN;Require(!loaded.Valid(),"Invalid interest accepted");loaded.trickInterest=1;loaded.nextTrickAt=-1;Require(!loaded.Valid(),"Invalid timer accepted");Debug.Log("BWVR_SPIN_AUDIENCE_MODEL_PASS: legacy saves, bounded interest/sentiment, cooldown and persistence");}
 public static void Verify(Action<BeachBall,VillagerExploration[]> capture=null){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var god=slice.GetComponentInChildren<CreatureHybrid>();var ball=slice.GetComponentInChildren<BeachBall>();var spin=ball.Spin;var item=ball.GetComponent<CarryItem>();var nav=god.GetComponent<IslandNavigator>();float unit=nav.world.Scale;var people=slice.GetComponentsInChildren<VillagerExploration>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var gp=god.transform.position;var gr=god.transform.rotation;var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(p=>p==null),"Release objects before QA");var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};GameObject blocker=null;var pair=people.Take(2).ToArray();
  void Stage(){god.Interrupt("Spin spectator QA");ball.ResetWorld();foreach(var p in people){p.GetComponent<VillagerSocial>().ResetTask();p.ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(p.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(p.GetComponent<VillagerRoutine>());p.GetComponent<CarryItem>().held=false;var m=p.GetComponent<VillagerSocial>().Memory;m.nextTrickAt=0;m.injury=1;m.lastFrightAt=-100;m.frights=0;p.transform.position+=Vector3.right*unit*300;}Require(nav.world.Sample(ball.Bowling.Start,nav.profile,5,out var foot),"No creature staging point");god.transform.SetPositionAndRotation(nav.world.ProjectFoot(foot,nav.profile),Quaternion.LookRotation(ball.Bowling.Forward));nav.ResetRoute();for(int i=0;i<2;i++){var p=pair[i];p.GetComponent<VillagerSocial>().Memory.injury=0;var walker=p.GetComponent<IslandNavigator>();bool found=false;for(int k=0;k<24&&!found;k++){float angle=(i==0?1:-1)*(60+k*10)*Mathf.Deg2Rad;var wanted=god.transform.position+(ball.Bowling.Right*Mathf.Sin(angle)+ball.Bowling.Forward*Mathf.Cos(angle))*unit*(14+k/8*4);if(!nav.world.Sample(wanted,walker.profile,2,out var at))continue;p.transform.position=nav.world.ProjectFoot(at,walker.profile);p.transform.LookAt(new Vector3(god.transform.position.x,p.transform.position.y,god.transform.position.z));Physics.SyncTransforms();found=p.CanSeeSpin(spin);}Require(found,"No visible spectator point");walker.ResetRoute();}item.held=true;held[1]=item;item.GetComponent<Collider>().enabled=false;ball.transform.position=god.transform.position+god.transform.forward*14*unit+Vector3.up*10*unit;typeof(BallSpin).GetField("pending",Flags).SetValue(spin,true);typeof(BallSpin).GetField("until",Flags).SetValue(spin,god.State.time+8);typeof(BallSpin).GetField("direction",Flags).SetValue(spin,1);Physics.SyncTransforms();}
  void Tick(float dt){foreach(var p in pair)p.Tick(dt,test.paused);if(!test.paused)test.Hybrid.time+=dt;spin.Step(dt);}
  try{
   field.SetValue(slice,test);god.NewSeason();Stage();Require(spin.Begin()&&spin.AudienceCount==2&&pair.All(p=>p.WatchingSpin),"Visible free villagers did not watch: "+spin.AudienceCount);Require(people.Skip(2).All(p=>!p.WatchingSpin),"Injured villagers recruited");Require(!spin.ReserveSpectator(pair[0])&&!spin.ReserveSpectator(people[2]),"Duplicate/overflow spectator reserved");Require(pair.All(p=>p.GetComponentInChildren<HumanoidHands>().resource==null),"Spectator retained work load");var feet=pair.Select(p=>p.transform.position).ToArray();Tick(.1f);test.paused=true;float angle=spin.Turned;Tick(1);Require(spin.Turned==angle&&pair.Select(p=>p.transform.position).SequenceEqual(feet),"Pause moved spectators or trick");test.paused=false;for(int i=0;i<40&&spin.Active;i++)Tick(.1f);Require(spin.JustCompleted&&spin.AudienceCount==0&&pair.All(p=>p.ApplaudingSpin),"Witnessed finish did not trigger applause");foreach(var p in pair)p.Tick(.1f,false);Require(pair.All(p=>p.GetComponentInChildren<HumanoidHands>().clap>0&&p.GetComponent<VillagerSocial>().Memory.tricksEnjoyed==1),"Applause/memory missing");capture?.Invoke(ball,pair);Require(pair.All(p=>!p.WitnessSpin(spin)),"Duplicate completion credited");Require(!test.Hybrid.receipt.eligible,"Audience fabricated a player training receipt");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Spectator save invalid");foreach(var p in pair)p.Tick(2,false);Require(pair.All(p=>!p.Active&&p.GetComponentInChildren<HumanoidHands>().clap==0),"Applause did not release motor/hand pose");
   Stage();var first=pair[0];var eye=first.transform.position+Vector3.up*unit*nav.world.villager.height*.8f;var end=god.GetComponent<Collider>().bounds.center;blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.name="Trick visibility QA";blocker.transform.position=(eye+end)*.5f;blocker.transform.localScale=Vector3.one*unit*5;Physics.SyncTransforms();Require(!first.CanSeeSpin(spin),"Sight blocker ineffective");Require(spin.Begin()&&!first.WatchingSpin,"Occluded villager joined");UnityEngine.Object.DestroyImmediate(blocker);blocker=null;spin.Cancel();Require(spin.AudienceCount==0&&pair.All(p=>!p.WatchingSpin),"Canceled trick retained watchers");
   Stage();Require(spin.Begin(),"Second trick did not begin");for(int i=0;i<12;i++)Tick(.1f);first.GetComponent<CarryItem>().held=true;first.Tick(.1f,false);Require(!first.Active&&spin.AudienceCount==1,"Picked-up spectator kept intention");first.GetComponent<CarryItem>().held=false;pair[1].GetComponent<VillagerSocial>().Memory.injury=.2f;pair[1].Tick(.1f,false);Require(spin.AudienceCount==0,"Injured spectator retained intention");for(int i=0;i<40&&spin.Active;i++)Tick(.1f);Require(pair.All(p=>p.GetComponent<VillagerSocial>().Memory.tricksEnjoyed==1),"Interrupted spectators gained rewards");
   Stage();Require(spin.Begin(),"Third trick did not begin");Tick(.5f);spin.Cancel();Require(spin.AudienceCount==0&&pair.All(p=>!p.Active&&p.GetComponentInChildren<HumanoidHands>().clap==0&&p.GetComponent<VillagerSocial>().Memory.tricksEnjoyed==1),"Partial turn rewarded / retained pose");
   Debug.Log("BWVR_SPIN_AUDIENCE_PLAY_PASS: two free visible healthy witnesses, workload stow, pause, completion applause, bounded saved enjoyment, no duplicate/training credit, occlusion, pickup/injury interruption and cleanup");
  }finally{if(blocker!=null)UnityEngine.Object.DestroyImmediate(blocker);spin.Cancel();foreach(var p in people){p.GetComponent<CarryItem>().held=false;p.ResetTask();}held[0]=held[1]=null;item.held=false;item.GetComponent<Collider>().enabled=true;field.SetValue(slice,original);god.NewSeason();god.transform.SetPositionAndRotation(gp,gr);nav.ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}ball.ResetWorld();Physics.SyncTransforms();}
 }
}
}
